    // One Code-node execution receives all keyword rows. Process every row so
    // no keyword is silently dropped when n8n batches items.
    const inputItems = $input.all();
    const allResults = [];
    for (const input of inputItems) {
      const workflowContext = input.json || {};
      const keywords = String(workflowContext.keywords || workflowContext.query || workflowContext.search || workflowContext.keyword || '').trim();
      if (!keywords) { console.log('Skipping empty keyword row'); continue; }
      console.log(`🔍 Searching: "${keywords}"`);

