const cfg = $('Runtime Config').first().json;
async function sheetRows(tab) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: `https://sheets.googleapis.com/v4/spreadsheets/${cfg.sheets.documentId}/values/${tab}`, headers: { Authorization: 'Bearer ' + (await this.helpers.getCredentials('googleSheetsOAuth2Api')).access_token }, json: true, timeout: 10000 });
    const vals = res.values || [];
    if (vals.length < 2) return [];
    const header = vals[0];
    return vals.slice(1).map(r => Object.fromEntries(header.map((h, i) => [h, r[i] || ''])));
  } catch (e) { throw new Error(`Could not read ${tab} suppression data; refusing follow-up sends: ${e.message}`); }
}
const replyRows = await sheetRows.call(this, cfg.sheets.replyLog);
const blacklistRows = await sheetRows.call(this, cfg.sheets.blacklist);
const historyRows = await sheetRows.call(this, cfg.sheets.emailHistory);
const replies = new Set(replyRows.map(r => String(r.email || '').toLowerCase().trim()).filter(Boolean));
const blacklist = new Set(blacklistRows.map(r => String(r.value || r.email || '').toLowerCase().trim()).filter(Boolean));
for (const r of historyRows) {
  const email = String(r.email || '').toLowerCase().trim();
  const status = String(r.status || '').toLowerCase();
  const replied = String(r.replied || '').toLowerCase() === 'true';
  if (email && (replied || status.includes('replied'))) replies.add(email);
  if (email && (status.includes('bounce') || status.includes('undeliver'))) blacklist.add(email);
}
const inRun = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const email = String(j.email || '').toLowerCase().trim();
  if (!email || inRun.has(email) || replies.has(email) || blacklist.has(email)) continue;
  inRun.add(email);
  out.push({ json: { ...j, email, shouldSend: true } });
}
return out;
